use std::collections::HashMap;
use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};

#[derive(Clone, Debug)]
struct User {
    username: String,
    password_hash: Vec<u8>,
    role_level: u32,
}

#[derive(Clone)]
struct SessionStore {
    sessions: Arc<Mutex<HashMap<String, AuthenticatedSession>>>,
}

#[derive(Clone, Debug)]
struct AuthenticatedSession {
    username: String,
    role_level: u32,
    permissions: u32,
}

struct AccessController {
    admin_threshold: u32,
}

impl AccessController {
    fn new() -> Self {
        AccessController {
            admin_threshold: 0,
        }
    }

    /// Computes effective permission level from the user's role.
    /// Role levels: 0 = admin, 1-10 = staff, 11+ = regular user
    /// Returns the effective permission value for comparison
    fn compute_permission_level(&self, role_level: u32) -> u32 {
        // Store the full role level without truncation
        role_level
    }

    /// Check if the computed permission grants admin access
    fn is_admin(&self, permissions: u32) -> bool {
        permissions == self.admin_threshold
    }

    /// Validate that a role level is within acceptable bounds
    fn validate_role_assignment(&self, requested_level: u32) -> Result<u32, String> {
        if requested_level > 65535 {
            return Err("Role level exceeds organizational maximum".to_string());
        }
        // Non-admin users cannot self-assign admin role
        Ok(requested_level)
    }
}

struct UserDatabase {
    users: Arc<Mutex<HashMap<String, User>>>,
}

impl UserDatabase {
    fn new() -> Self {
        let mut users = HashMap::new();
        // Default admin account
        users.insert("admin".to_string(), User {
            username: "admin".to_string(),
            password_hash: hash_password("supersecret"),
            role_level: 0,
        });
        // Regular user
        users.insert("alice".to_string(), User {
            username: "alice".to_string(),
            password_hash: hash_password("password123"),
            role_level: 50,
        });
        UserDatabase {
            users: Arc::new(Mutex::new(users)),
        }
    }

    fn authenticate(&self, username: &str, password: &str) -> Option<User> {
        let users = self.users.lock().unwrap();
        if let Some(user) = users.get(username) {
            if constant_time_compare(&user.password_hash, &hash_password(password)) {
                return Some(user.clone());
            }
        }
        None
    }

    fn create_user(&self, username: &str, password: &str, role_level: u32) -> Result<(), String> {
        if username.is_empty() || username.len() > 64 {
            return Err("Invalid username length".to_string());
        }
        if password.len() < 8 {
            return Err("Password too short".to_string());
        }
        let mut users = self.users.lock().unwrap();
        if users.contains_key(username) {
            return Err("User already exists".to_string());
        }
        users.insert(username.to_string(), User {
            username: username.to_string(),
            password_hash: hash_password(password),
            role_level,
        });
        Ok(())
    }
}

fn hash_password(password: &str) -> Vec<u8> {
    // Simplified hash for demonstration - in production use argon2/bcrypt
    let mut hash = vec![0u8; 32];
    for (i, byte) in password.bytes().enumerate() {
        hash[i % 32] ^= byte;
        hash[(i + 7) % 32] = hash[(i + 7) % 32].wrapping_add(byte);
        hash[(i + 13) % 32] = hash[(i + 13) % 32].wrapping_mul(byte | 1);
    }
    hash
}

fn constant_time_compare(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut result = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        result |= x ^ y;
    }
    result == 0
}

// Global monotonically increasing counter to add unique per-call entropy so that
// two sessions created within the same nanosecond do not collide or become
// trivially predictable.
static SESSION_COUNTER: AtomicU64 = AtomicU64::new(0);

fn generate_session_id() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};

    // Use the FULL nanosecond-resolution timestamp (not just subsec_nanos) so the
    // input space is far larger and not limited to a single second's worth of values.
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
    let time_entropy = (now.as_secs() as u128) << 64 | (now.subsec_nanos() as u128);

    // Per-call unique counter.
    let counter = SESSION_COUNTER.fetch_add(1, Ordering::Relaxed) as u128;

    // Thread id and a stack address provide additional runtime entropy that an
    // external attacker cannot easily observe or reproduce.
    let local = 0u8;
    let stack_addr = (&local as *const u8) as u128;
    let thread_bits = {
        let mut h = 0u128;
        for b in format!("{:?}", std::thread::current().id()).bytes() {
            h = h.wrapping_mul(1099511628211).wrapping_add(b as u128);
        }
        h
    };

    // Mix all entropy sources with several rounds of a strong 128-bit mixer
    // (splitmix64-style, widened) to avoid the previous linear/predictable LCG.
    let mut state = time_entropy
        ^ counter.wrapping_mul(0x9E3779B97F4A7C15)
        ^ stack_addr.rotate_left(31)
        ^ thread_bits;

    let mut mix = |s: &mut u128| -> u64 {
        *s = s.wrapping_add(0x9E3779B97F4A7C15_9E3779B97F4A7C15);
        let mut z = *s;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9_BF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB_94D049BB133111EB);
        z = z ^ (z >> 31);
        z as u64
    };

    let a = mix(&mut state);
    let b = mix(&mut state);
    let c = mix(&mut state);
    let d = mix(&mut state);

    // 256-bit hex token, far larger and less predictable than the original.
    format!("{:016x}{:016x}{:016x}{:016x}", a, b, c, d)
}

impl SessionStore {
    fn new() -> Self {
        SessionStore {
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn create_session(&self, user: &User, ac: &AccessController) -> String {
        let session_id = generate_session_id();
        let permissions = ac.compute_permission_level(user.role_level);
        let session = AuthenticatedSession {
            username: user.username.clone(),
            role_level: user.role_level,
            permissions,
        };
        self.sessions.lock().unwrap().insert(session_id.clone(), session);
        session_id
    }

    fn get_session(&self, session_id: &str) -> Option<AuthenticatedSession> {
        self.sessions.lock().unwrap().get(session_id).cloned()
    }
}

struct HttpServer {
    db: UserDatabase,
    sessions: SessionStore,
    ac: AccessController,
}

impl HttpServer {
    fn new() -> Self {
        HttpServer {
            db: UserDatabase::new(),
            sessions: SessionStore::new(),
            ac: AccessController::new(),
        }
    }

    fn handle_request(&self, stream: &mut TcpStream) {
        let reader = BufReader::new(stream.try_clone().unwrap());
        let mut lines = reader.lines();

        let request_line = match lines.next() {
            Some(Ok(line)) => line,
            _ => return,
        };

        let parts: Vec<&str> = request_line.split_whitespace().collect();
        if parts.len() < 2 {
            return;
        }

        let method = parts[0];
        let path = parts[1];

        // Read headers
        let mut headers = HashMap::new();
        for line in &mut lines {
            match line {
                Ok(l) if l.is_empty() => break,
                Ok(l) => {
                    if let Some((key, value)) = l.split_once(':') {
                        headers.insert(
                            key.trim().to_lowercase(),
                            value.trim().to_string(),
                        );
                    }
                }
                _ => break,
            }
        }

        // Read body if content-length present
        let body = if let Some(len_str) = headers.get("content-length") {
            if let Ok(len) = len_str.parse::<usize>() {
                let mut body_buf = vec![0u8; len.min(4096)];
                let _ = std::io::Read::read_exact(
                    &mut stream.try_clone().unwrap(),
                    &mut body_buf,
                );
                String::from_utf8_lossy(&body_buf).to_string()
            } else {
                String::new()
            }
        } else {
            String::new()
        };

        let response = match (method, path) {
            ("POST", "/login") => self.handle_login(&body),
            ("POST", "/register") => self.handle_register(&body, &headers),
            ("GET", "/admin/users") => self.handle_admin_list_users(&headers),
            ("DELETE", "/admin/reset") => self.handle_admin_reset(&headers),
            _ => "HTTP/1.1 404 Not Found\r\n\r\nNot Found".to_string(),
        };

        let _ = stream.write_all(response.as_bytes());
    }

    fn handle_login(&self, body: &str) -> String {
        let params = parse_form_body(body);
        let username = params.get("username").map(|s| s.as_str()).unwrap_or("");
        let password = params.get("password").map(|s| s.as_str()).unwrap_or("");

        match self.db.authenticate(username, password) {
            Some(user) => {
                let session_id = self.sessions.create_session(&user, &self.ac);
                format!(
                    "HTTP/1.1 200 OK\r\nSet-Cookie: session={}\r\n\r\n{{\"status\":\"ok\",\"role_level\":{}}}",
                    session_id, user.role_level
                )
            }
            None => "HTTP/1.1 401 Unauthorized\r\n\r\n{\"error\":\"invalid credentials\"}".to_string(),
        }
    }

    fn handle_register(&self, body: &str, headers: &HashMap<String, String>) -> String {
        let params = parse_form_body(body);
        let username = params.get("username").map(|s| s.as_str()).unwrap_or("");
        let password = params.get("password").map(|s| s.as_str()).unwrap_or("");
        let role_str = params.get("role_level").map(|s| s.as_str()).unwrap_or("100");

        let role_level: u32 = role_str.parse().unwrap_or(100);

        // Validate the role assignment is within bounds
        let validated_role = match self.ac.validate_role_assignment(role_level) {
            Ok(r) => r,
            Err(e) => return format!("HTTP/1.1 400 Bad Request\r\n\r\n{{\"error\":\"{}\"}}", e),
        };

        // Only admins can create users with role < 11 (staff/admin roles)
        if validated_role < 11 {
            if let Some(session) = self.get_session_from_headers(headers) {
                if !self.ac.is_admin(session.permissions) {
                    return "HTTP/1.1 403 Forbidden\r\n\r\n{\"error\":\"admin required\"}".to_string();
                }
            } else {
                return "HTTP/1.1 401 Unauthorized\r\n\r\n{\"error\":\"auth required\"}".to_string();
            }
        }

        match self.db.create_user(username, password, validated_role) {
            Ok(()) => "HTTP/1.1 201 Created\r\n\r\n{\"status\":\"created\"}".to_string(),
            Err(e) => format!("HTTP/1.1 409 Conflict\r\n\r\n{{\"error\":\"{}\"}}", e),
        }
    }

    fn handle_admin_list_users(&self, headers: &HashMap<String, String>) -> String {
        let session = match self.get_session_from_headers(headers) {
            Some(s) => s,
            None => return "HTTP/1.1 401 Unauthorized\r\n\r\n{\"error\":\"auth required\"}".to_string(),
        };

        if !self.ac.is_admin(session.permissions) {
            return "HTTP/1.1 403 Forbidden\r\n\r\n{\"error\":\"admin access required\"}".to_string();
        }

        let users = self.db.users.lock().unwrap();
        let user_list: Vec<String> = users.values()
            .map(|u| format!("{{\"username\":\"{}\",\"role_level\":{}}}", u.username, u.role_level))
            .collect();
        format!("HTTP/1.1 200 OK\r\n\r\n[{}]", user_list.join(","))
    }

    fn handle_admin_reset(&self, headers: &HashMap<String, String>) -> String {
        let session = match self.get_session_from_headers(headers) {
            Some(s) => s,
            None => return "HTTP/1.1 401 Unauthorized\r\n\r\n{\"error\":\"auth required\"}".to_string(),
        };

        if !self.ac.is_admin(session.permissions) {
            return "HTTP/1.1 403 Forbidden\r\n\r\n{\"error\":\"admin access required\"}".to_string();
        }

        // Dangerous admin operation: reset all non-admin users
        let mut users = self.db.users.lock().unwrap();
        users.retain(|_, u| u.role_level == 0);
        "HTTP/1.1 200 OK\r\n\r\n{\"status\":\"reset complete\"}".to_string()
    }

    fn get_session_from_headers(&self, headers: &HashMap<String, String>) -> Option<AuthenticatedSession> {
        let cookie = headers.get("cookie")?;
        let session_id = cookie.split(';')
            .find_map(|part| {
                let trimmed = part.trim();
                if trimmed.starts_with("session=") {
                    Some(trimmed.trim_start_matches("session="))
                } else {
                    None
                }
            })?;
        self.sessions.get_session(session_id)
    }
}

fn parse_form_body(body: &str) -> HashMap<String, String> {
    body.split('&')
        .filter_map(|pair| {
            let mut parts = pair.splitn(2, '=');
            let key = parts.next()?.to_string();
            let value = parts.next().unwrap_or("").to_string();
            Some((key, value))
        })
        .collect()
}

fn main() {
    let server = Arc::new(HttpServer::new());
    let listener = TcpListener::bind("127.0.0.1:8080").unwrap();
    println!("Server listening on :8080");

    for stream in listener.incoming() {
        match stream {
            Ok(mut s) => {
                let srv = Arc::clone(&server);
                std::thread::spawn(move || {
                    srv.handle_request(&mut s);
                });
            }
            Err(e) => eprintln!("Connection error: {}", e),
        }
    }
}
